function maxTradingProfit(prices: number[]): number {
  let cash = 0, hold = -prices[0];
  for (let i = 1; i < prices.length; i++) {
    const nextCash = Math.max(cash, hold + prices[i]);
    const nextHold = Math.max(hold, cash - prices[i]);
    cash = nextCash;
    hold = nextHold;
  }
  return cash;
}

